  denunciaPreview: any = null;

  // Reporte detallado
  reporteDetallado: any = null;

  // Componentes compartidos
  isSidebarCollapsed = false;
  isDarkTheme = false;
  showHelpSupport = false;
  isMinimized = false;
  isSearchOpen = false;
  searchQuery = '';
