import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { environment } from '../../../../environments/environment';

export interface Notificacion {
  notificacion_id: number;
  denuncia_id: number;
  tipo_notificacion_id: number;
  fecha_emision: string;
  destinatario: string;
  medio: string;
  contenido: string;
  estado: string;
  observaciones: string;
  denuncia?: DenunciaPreview;
  tipo_notificacion?: TipoNotificacion;
}

export interface DenunciaPreview {
  denuncia_id: number;
  numero_expediente: string;
  persona: {
    nombres: string;
    apellidos: string;
  };
  descripcion: string;
  fecha_ingreso: string;
}

export interface TipoNotificacion {
  tipo_notificacion_id: number;
  nombre: string;
  descripcion: string;
  activo: boolean;
}

export interface PaginatedResponse<T> {
  success: boolean;
  data: T[];
  pagination: {
    current_page: number;
    per_page: number;
    total: number;
    last_page: number;
  };
  estadisticas: Estadisticas;
}

export interface Estadisticas {
  total: number;
  emitidas: number;
  pendientes: number;
  canceladas: number;
  entregadas: number;
}

export interface FiltrosNotificacion {
  fecha_inicio?: string;
  fecha_fin?: string;
  tipo_notificacion?: number;
  estado?: string;
  destinatario?: string;
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  private http = inject(HttpClient);
  private baseUrl = `${environment.apiUrl}/notificaciones`;

  listarNotificaciones(filtros: FiltrosNotificacion, page: number = 1, perPage: number = 10): Observable<PaginatedResponse<Notificacion>> {
    let params = new HttpParams()
      .set('page', page.toString())
      .set('per_page', perPage.toString());

    Object.entries(filtros).forEach(([key, value]) => {
      if (value !== null && value !== undefined && value !== '') {
        params = params.set(key, value.toString());
      }
    });

    return this.http.get<PaginatedResponse<Notificacion>>(this.baseUrl, { params });
  }

  obtenerNotificacion(id: number): Observable<Notificacion> {
    return this.http.get<{ success: boolean; data: Notificacion }>(`${this.baseUrl}/${id}`)
      .pipe(map(res => res.data));
  }

  crearNotificacion(data: Partial<Notificacion>): Observable<Notificacion> {
    return this.http.post<{ success: boolean; data: Notificacion }>(this.baseUrl, data)
      .pipe(map(res => res.data));
  }

  actualizarNotificacion(id: number, data: Partial<Notificacion>): Observable<Notificacion> {
    return this.http.put<{ success: boolean; data: Notificacion }>(`${this.baseUrl}/${id}`, data)
      .pipe(map(res => res.data));
  }

  cancelarNotificacion(id: number, motivo: string): Observable<void> {
    return this.http.post<void>(`${this.baseUrl}/${id}/cancelar`, { motivo });
  }

  obtenerEstadisticas(filtros: FiltrosNotificacion): Observable<Estadisticas> {
    let params = new HttpParams();
    if (filtros.fecha_inicio) params = params.set('fecha_inicio', filtros.fecha_inicio);
    if (filtros.fecha_fin) params = params.set('fecha_fin', filtros.fecha_fin);

    return this.http.get<{ success: boolean; data: Estadisticas }>(`${this.baseUrl}/estadisticas`, { params })
      .pipe(map(res => res.data));
  }

  obtenerTiposNotificacion(): Observable<TipoNotificacion[]> {
    return this.http.get<{ success: boolean; data: TipoNotificacion[] }>(`${this.baseUrl}/tipos`)
      .pipe(map(res => res.data));
  }

  obtenerDenunciasDisponibles(): Observable<any[]> {
    return this.http.get<{ success: boolean; data: any[] }>(`${this.baseUrl}/denuncias-disponibles`)
      .pipe(map(res => res.data));
  }

generarConstancia(id: number): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/${id}/constancia`, {
        responseType: 'blob'
    });
}

  exportarExcelIndividual(id: number): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/${id}/exportar-excel`, {
      responseType: 'blob'
    });
  }

  exportarExcel(filtros: FiltrosNotificacion): Observable<Blob> {
    let params = new HttpParams();
    Object.entries(filtros).forEach(([key, value]) => {
        if (value) params = params.set(key, value.toString());
    });

    return this.http.get(`${this.baseUrl}/exportar-excel`, {
        params,
        responseType: 'blob'
    });
}

exportarReporteCompletoPDF(filtros: FiltrosNotificacion): Observable<Blob> {
    let params = new HttpParams();
    Object.entries(filtros).forEach(([key, value]) => {
        if (value) params = params.set(key, value.toString());
    });
    return this.http.get(`${this.baseUrl}/reporte-completo-pdf`, {
        params,
        responseType: 'blob'
    });
}

exportarReporteCompletoExcel(filtros: FiltrosNotificacion): Observable<Blob> {
    let params = new HttpParams();
    Object.entries(filtros).forEach(([key, value]) => {
        if (value) params = params.set(key, value.toString());
    });
    return this.http.get(`${this.baseUrl}/reporte-completo-excel`, {
        params,
        responseType: 'blob'
    });
}

enviarReportePorCorreo(filtros: FiltrosNotificacion, email: string): Observable<void> {
    return this.http.post<void>(`${this.baseUrl}/enviar-reporte`, { ...filtros, email });
}

  obtenerReporteDetallado(filtros: FiltrosNotificacion): Observable<any> {
    let params = new HttpParams();
    Object.entries(filtros).forEach(([key, value]) => {
      if (value !== null && value !== undefined && value !== '') {
        params = params.set(key, value.toString());
      }
    });

    return this.http.get<{ success: boolean; data: any }>(`${this.baseUrl}/reporte-detallado`, { params })
      .pipe(map(res => res.data));
  }
}
